define("TranslationStatusPageResources",["terrasoft"],function(){return{localizableStrings:{QuickFilter_yt46o13_config_caption:"Культура",QuickFilter_yt46o13_caption:"Быстрый фильтр",PageTitle_caption:"Результат проверки переводов",Button_Back_caption:"Назад",TabTitleLabel_caption:"Справка",HelpTabPanel_caption:"Справка",Label_Paragraph_1_caption:"Эта страница отображает различия между переводами в интерфейсе приложения и значениями, заданными в разделе Переводы. Ниже приведено описание каждой колонки и шаги, которые помогут устранить выявленные несоответствия. ",MenuItem_OpenTranslationSection_caption:"Переводы",Label_rwqe5bc_caption:"•",Label_StaticContentHint_caption:"Если обнаружено несоответствие между ожидаемым значением и значением статического контента, воспользуйтесь действием Компиляция в разделе Управление конфигурацией. Это обновит содержимое статического контента, чтобы переводы на страницах Creatio отображались корректно. ",Label_StaticContentBullet_caption:"•",Label_BusinessProcessBullet_caption:"•",Label_BusinessProcessHint_caption:"Если обнаружено несоответствие между фактическим и ожидаемым значениями, выполните бизнес-процесс Применить переводы. Это обновит локализацию интерфейса в соответствии со значениями из раздела Переводы.",Label_ApplyChangesHintTitle_caption:"2. Примените исправления",Label_ErrorsHint_caption:"Для каждого ключа, указанного в результатах валидации, проверьте поле Ошибка в разделе Переводы. Перед применением исправлений убедитесь, что все ошибки устранены.",Label_ErrorHintTitle_caption:"1. Проверьте и устраните ошибки в разделе Переводы",Label_ResolutionsContainerTitle_caption:"Как устранить ошибки ",Label_StaticContentValueDescription_caption:"• Значение статического контента — значение, найденное в локализируемых ресурсах элементов страницы, например, в заголовках кнопок. Эта колонка заполняется только для тех переводов, которые имеют соответствующий ресурс в страницах приложения.",Label_ActualValueDescription_caption:"• Фактическое значение — значение, которое в данный момент хранится в локализиованных значениях элементов конфигурации и данных. Различие между ожидаемым и фактическим значением указывает на то, что последние изменения ещё не были применены.",Label_ExpectedValueDescription_caption:"• Ожидаемое значение — перевод, заданный в разделе Переводы. ",Label_CultureColumnDescription_caption:"• Культура — указывает культуру, в которой было обнаружено несоответствие. ",Label_KeyColumnDescription_caption:"• Ключ — соответствует полю Ключ в разделе Переводы.",ActionButton_caption:"Действия",AddButton:"Добавить",Button_Data_Import:"Импорт",DefaultHeaderCaption:"Результат проверки переводов",EmptySectionPlaceholderSubHead:"Добавьте новую запись, и в разделе не будет так одиноко",EmptySectionPlaceholderTitle:"В разделе нет ни одной записи",FilteredEmptySectionPlaceholderSubHead:"Очистите фильтр или измените условия фильтрации",FilteredEmptySectionPlaceholderTitle:"При установленном фильтре в разделе нет ни одной записи",ListTitleCaption:"Название списка",LookupQuickFilterByTag_config_caption:"Тег",LookupQuickFilterByTag_config_hint:"Выберите тег для фильтрации",MenuItem_ExportToExcel_caption:"Экспорт в Excel",MenuItem_ImportFromExcel_caption:"Excel",OpenLandingDesignerCaption:"Web-формы и страницы",RefreshButtonCaption:"Обновить",SearchFilter_placeholder:"Поиск"},localizableImages:{},parametersLocalizableStrings:{},propertiesLocalizableStrings:{Caption:"Результат проверки переводов"}}})
